import{_ as e,o as a,c as o,ag as r}from"./chunks/framework.qXLDknWC.js";const g=JSON.parse('{"title":"Lorebook Vault","description":"","frontmatter":{},"headers":[],"relativePath":"features/lorebook-vault.md","filePath":"features/lorebook-vault.md"}'),s={name:"features/lorebook-vault.md"};function n(l,t,i,h,d,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="lorebook-vault" tabindex="-1">Lorebook Vault <a class="header-anchor" href="#lorebook-vault" aria-label="Permalink to &quot;Lorebook Vault&quot;">​</a></h1><p>Standalone <strong>SillyTavern-compatible lorebooks</strong> (World Info) live in their own library, separate from character cards. Create, edit, import, export, and snapshot books without opening a character. You can <strong>link</strong> a library book to one or more characters so they share the same entries.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The entry editor is the same one you see on a character’s <strong>Lorebook</strong> tab. Field details, recursion map, and AI key generation are covered in <a href="/CharacterVault/docs/features/lorebook-editor">Lorebook Editor</a>.</p></div><h2 id="characters-vs-lorebooks" tabindex="-1">Characters vs Lorebooks <a class="header-anchor" href="#characters-vs-lorebooks" aria-label="Permalink to &quot;Characters vs Lorebooks&quot;">​</a></h2><p>On the home vault screen, switch between:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Tab</th><th style="text-align:left;">What it is</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Characters</strong></td><td style="text-align:left;">Portrait grid of character cards (existing library)</td></tr><tr><td style="text-align:left;"><strong>Lorebooks</strong></td><td style="text-align:left;">Standalone world-info books</td></tr></tbody></table><p>Your last tab choice is remembered in the browser.</p><h2 id="library" tabindex="-1">Library <a class="header-anchor" href="#library" aria-label="Permalink to &quot;Library&quot;">​</a></h2><p>From the <strong>Lorebooks</strong> tab you can:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Action</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Search</strong></td><td style="text-align:left;">Filter by name, description, or tags</td></tr><tr><td style="text-align:left;"><strong>Create</strong></td><td style="text-align:left;">New empty book; opens in the lorebook workspace</td></tr><tr><td style="text-align:left;"><strong>Import</strong></td><td style="text-align:left;">One or more SillyTavern / CharacterVault lorebook JSON files</td></tr><tr><td style="text-align:left;"><strong>Open</strong></td><td style="text-align:left;">Click a row to edit the book</td></tr><tr><td style="text-align:left;"><strong>Export</strong></td><td style="text-align:left;">Download that book as JSON</td></tr><tr><td style="text-align:left;"><strong>Duplicate</strong></td><td style="text-align:left;">Copy the book in the vault</td></tr><tr><td style="text-align:left;"><strong>Delete</strong></td><td style="text-align:left;">Remove the book after confirmation</td></tr></tbody></table><p>Each row shows name, description (if any), entry count, and last opened / updated time.</p><h2 id="workspace" tabindex="-1">Workspace <a class="header-anchor" href="#workspace" aria-label="Permalink to &quot;Workspace&quot;">​</a></h2><p>Opening a book shows a full workspace:</p><ul><li><strong>Header</strong> – Back to vault, editable title, entry/token summary, <strong>History</strong> (snapshots), export, optional chat panel</li><li><strong>Main</strong> – Shared <a href="/CharacterVault/docs/features/lorebook-editor">Lorebook Editor</a> (entry list + detail)</li><li><strong>Chat</strong> – Optional side panel: <strong>Orion</strong> to talk about the book, or <strong>Agent</strong> to add and revise entries in this book (<a href="/CharacterVault/docs/features/ai-agent">AI Agent</a>)</li></ul><p>Data stays in <strong>IndexedDB</strong> on this device. No account is required.</p><h3 id="deep-links" tabindex="-1">Deep links <a class="header-anchor" href="#deep-links" aria-label="Permalink to &quot;Deep links&quot;">​</a></h3><p>You can open a book with a query parameter:</p><p><code>?lorebook=&lt;lorebook-id&gt;</code></p><h2 id="snapshots" tabindex="-1">Snapshots <a class="header-anchor" href="#snapshots" aria-label="Permalink to &quot;Snapshots&quot;">​</a></h2><p>Standalone books have their own snapshot history (similar to character snapshots):</p><table tabindex="0"><thead><tr><th style="text-align:left;">Source</th><th style="text-align:left;">When</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Opened</strong></td><td style="text-align:left;">Baseline when the book is first opened. You can update it in place; you cannot delete it. It stays last in the list.</td></tr><tr><td style="text-align:left;"><strong>Manual</strong></td><td style="text-align:left;"><strong>Snapshot now</strong> in the History modal (only if something changed)</td></tr><tr><td style="text-align:left;"><strong>Rollback</strong></td><td style="text-align:left;">After restoring a previous snapshot</td></tr></tbody></table><p>Open <strong>History</strong> in the workspace header to list, preview, restore, or delete snapshots. See also <a href="/CharacterVault/docs/features/snapshots-history#standalone-lorebook-snapshots">Snapshots &amp; Rollback</a>.</p><h2 id="attach-to-a-character-vault-local" tabindex="-1">Linking a book to a character <a class="header-anchor" href="#attach-to-a-character-vault-local" aria-label="Permalink to &quot;Linking a book to a character {#attach-to-a-character-vault-local}&quot;">​</a></h2><p>A character can have <strong>one</strong> linked library book. Several characters can share that same book.</p><p>Manage the link from a <strong>character</strong> → <strong>Lorebook</strong> tab → <strong>Attach</strong> in the entry header (next to <strong>Options</strong>). On a phone, <strong>Attach</strong> is also next to book settings on the entry list.</p><h3 id="first-link" tabindex="-1">First link <a class="header-anchor" href="#first-link" aria-label="Permalink to &quot;First link&quot;">​</a></h3><ol><li>Click <strong>Attach</strong> and pick a book (or <strong>Replace</strong> if one is already linked).</li><li>CharacterVault asks if you want to copy that book’s entries onto the character. Confirming <strong>replaces</strong> the lorebook already on the character.</li><li>You can copy again later from the panel without changing the link.</li></ol><p>If nothing is linked yet, <strong>Open in vault</strong> can create a library book from the character’s current lorebook, link it, and open it.</p><h3 id="how-they-stay-in-sync" tabindex="-1">How they stay in sync <a class="header-anchor" href="#how-they-stay-in-sync" aria-label="Permalink to &quot;How they stay in sync&quot;">​</a></h3><p>Once linked, the library book and the lorebook on the character are kept together:</p><table tabindex="0"><thead><tr><th style="text-align:left;">You do this</th><th style="text-align:left;">What happens</th></tr></thead><tbody><tr><td style="text-align:left;">Edit the lorebook on the character, then <strong>Open in vault</strong></td><td style="text-align:left;">The library book updates to match, then opens</td></tr><tr><td style="text-align:left;">Edit the book in the Lorebooks workspace</td><td style="text-align:left;">Every linked character’s lorebook updates</td></tr><tr><td style="text-align:left;">Restore a snapshot of the library book</td><td style="text-align:left;">Linked characters get that restored version too</td></tr></tbody></table><p>Leaving the lorebook workspace (back to the library, or opening a linked character) finishes any pending update first.</p><h3 id="export-detach-and-sharing" tabindex="-1">Export, detach, and sharing <a class="header-anchor" href="#export-detach-and-sharing" aria-label="Permalink to &quot;Export, detach, and sharing&quot;">​</a></h3><ul><li><strong>Exporting a character</strong> (PNG or JSON) includes the lorebook <strong>on that character</strong>, not the link itself. After a sync, those entries are on the card, so they go with the export.</li><li><strong>Detach</strong> breaks the link. The character keeps whatever was last on the card. The library book stays in <strong>Lorebooks</strong>.</li><li>Linking another book replaces the previous link (you’ll be asked first).</li><li>If you do <strong>not</strong> want a character to follow later library edits, <strong>Detach</strong> it first.</li></ul><h3 id="linked-characters-from-the-book" tabindex="-1">Linked characters (from the book) <a class="header-anchor" href="#linked-characters-from-the-book" aria-label="Permalink to &quot;Linked characters (from the book)&quot;">​</a></h3><p>In the lorebook workspace, <strong>Linked</strong> lists characters that use this book. Opening one of them saves the book first so the character already has your latest edits.</p><h2 id="import-export-formats" tabindex="-1">Import &amp; export formats <a class="header-anchor" href="#import-export-formats" aria-label="Permalink to &quot;Import &amp; export formats&quot;">​</a></h2><p>Import accepts SillyTavern world-info JSON and CharacterVault lorebook shapes (including <code>character_book</code> / <code>entries</code> layouts used by the shared converter). Export produces ST-oriented JSON suitable for SillyTavern and re-import into the vault or a character’s lorebook editor.</p><p>See <a href="/CharacterVault/docs/features/import-export#lorebook-import--export">Import &amp; Export</a> and <a href="/CharacterVault/docs/features/lorebook-editor#import--export">Lorebook Editor → Import &amp; Export</a>.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/CharacterVault/docs/features/lorebook-editor">Lorebook Editor</a> (fields, recursion map, AI keys)</li><li><a href="/CharacterVault/docs/features/ai-context">AI Context</a></li><li><a href="/CharacterVault/docs/features/ai-agent">AI Agent</a></li><li><a href="/CharacterVault/docs/features/vault-organization">Vault Organization</a></li><li><a href="/CharacterVault/docs/features/snapshots-history">Snapshots &amp; Rollback</a></li></ul>',41)])])}const b=e(s,[["render",n]]);export{g as __pageData,b as default};
